			"options": {
				"preserveAspectRatio": true,
				"src": "splunk-enterprise-kvstore://654fcb377ce238ea0103b068"
			}
		}
	},
	"dataSources": {
		"ds_gLEbG3o2": {
			"type": "ds.search",
			"options": {
				"query": "index=_internal source=\"/opt/splunk/var/log/splunk/ta_microsoft_public_ip_generic_microsoft_public_ip.log\" sourcetype=\"tamicrosoftpublicipgeneric:log\" ",
				"enableSmartSources": true
			},
			"name": "basefilter"
		},
		"ds_PEUtKKqU": {
			"type": "ds.chain",
			"options": {
				"query": "Search \"Indexed * events\" \n| rex field=_raw \"source=(?<input>[^ ]+)\" \n| timechart count by input",
				"extend": "ds_gLEbG3o2"
			},
			"name": "connection to microsoft"
		},
		"ds_eWXtDXNx": {
			"type": "ds.search",
			"options": {
				"query": "index=_internal source=\"/opt/splunk/var/log/splunk/ta_microsoft_public_ip_generic_microsoft_public_ip.log\" sourcetype=\"tamicrosoftpublicipgeneric:log\"  src=* src!=\"{}\"  status!=TEST | stats  count by src, dest, status \n|  fields - count",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"name": "nodes_connection"
		},
		"ds_cH8dxy3D": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_gLEbG3o2",
				"query": " | search \"Indexed * events\"| rex field=_raw \"Indexed (?<event_count>\\d+) events\"\r\n| stats sum(event_count)"
			},
			"name": "Msft to Splunk"
		},
		"ds_mJi0UNa1": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_gLEbG3o2",
				"query": "|  search \"Destination : internet\" \n| stats count"
			},
			"name": "host to internet"
		},
		"ds_adwcMlaD": {
			"type": "ds.chain",
			"options": {
				"query": " | search \"Destination : microsoft\" ",
				"extend": "ds_gLEbG3o2"
			},
			"name": "host to msft"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"latest": "$global_time.latest$",
						"earliest": "$global_time.earliest$"
					}
				}
			}
		}
	},
	"inputs": {
		"input_global_trp": {
			"type": "input.timerange",
			"options": {
				"token": "global_time",
				"defaultValue": "-60m@m,now"
			},
			"title": "Global Time Range"
		}
	},
